from lib import *
S = SS('x61')
steps = [
    step("R2DBC 也是惰性的。repo.save(new User(null, \"lazy-no-sub\")) 调用后不订阅,等 300 ms:库里 'lazy-no-sub' 的行数 = 0,没有发出任何 INSERT。repo.save(...).block():返回带 id=1 的实体,库里 'lazy-sub' 的行数 = 1。repo.findAll().count().block() = 1;DatabaseClient 的 sql(...).map(...).all().collectList().block() 得到 [lazy-sub]。和 JDBC 不同,调用方法不会发 SQL,订阅才发。", t=tl(S(1)), mark=lidx(S(1), 'lazy-no-sub'), done=lidx(S(1), '返回的实体 id', 'findAll', 'collectList'), b=bars([['不订阅 save 后库里的行数', 0, '0'], ['block() 后库里的行数', 1, '1']], 1, mark=[0], done=[1]), kv=KV([['repo.save(...)', '只是一个描述,不订阅不执行'], ['.block() / subscribe', '才发 INSERT'], ['返回实体', '带数据库生成的 id'], ['DatabaseClient', '同样是惰性的']], ['repo.save(...)'])),
    step("没有事务时,同一个方法里的两条语句用的是不是同一个连接。pg_backend_pid() 看服务端进程号:无事务的第一次调用,两条语句 pid 都是 19925;再来一次,pid 分别是 19926 和 19927——两条语句拿到了不同的连接。@Transactional 的方法,两次调用都是 19927 和 19927,两条语句在同一个连接里。没有事务时,连接是每条语句从池里临时取的,不保证是同一个;要同一个连接(同一个会话、同一个事务)必须在事务里。", t=tl(S(2)), mark=lidx(S(2), 'pid=19926,第二条语句 pid=19927'), done=lidx(S(2), '@Transactional'), b=bars([['无事务第二次:两条语句用到的连接数', 2, '2(19926、19927)'], ['@Transactional:两条语句用到的连接数', 1, '1(19927)']], 2, mark=[0], done=[1]), kv=KV([['无事务', '每条语句从池里取连接,可能不是同一个'], ['@Transactional', '整个事务绑定一个连接'], ['结果', '同一个方法里的语句,事务外可能落在不同连接上'], ['连接级的状态', '(临时表、会话变量)事务外不能依赖']], ['无事务'])),
    step("事务的回滚。保存两行再抛 IllegalStateException:没有事务,两行都留下(2 行);@Transactional,0 行,全部回滚;TransactionalOperator(.as(tx::transactional)),0 行。陷阱:@Transactional 的方法里写 repo.save(...).subscribe() 然后返回 Mono.error:库里仍有 1 行——subscribe() 起的是一条独立的订阅,不在事务的上下文里,用另一个连接、自动提交;同样,在 boundedElastic 上调用 save().block() 也留下 1 行。事务绑定在这条响应式链上,脱离这条链的写法不在事务里。", t=tl(S(3)), mark=lidx(S(3), 'forgot', 'block-inside'), done=lidx(S(3), "'tx-'", "'op-'"), b=bars([['没有事务:留下的行数', 2, '2'], ['@Transactional:留下的行数', 0, '0'], ['TransactionalOperator:留下的行数', 0, '0'], ['subscribe() 脱链写法:留下的行数', 1, '1(没回滚)']], 2, done=[1, 2], mark=[0, 3]), kv=KV([['没有事务', '第一条写入已提交,后面失败不回滚'], ['@Transactional / TransactionalOperator', '整条链回滚'], ['链外 subscribe() / block()', '不在事务里,写入已提交'], ['原则', '事务内所有操作必须接在同一条链上']], ['链外 subscribe() / block()'])),
    step("连接池。30 个并发的 pg_sleep(300 ms),轮询 pg_stat_activity 取同时存在的最大连接数:默认的 R2DBC 连接池服务端最多同时 10 个连接,总用时 1100 ms;spring.r2dbc.pool.max-size=3:最多 3 个连接,总用时 3182 ms;max-size=30:30 个连接,523 ms。池满后请求排队,不报错。max-size=2、max-acquire-time=200ms、10 个并发的 pg_sleep(600 ms):只有 2 个成功,另外 8 个失败,异常链是 DataAccessResourceFailureException ← R2dbcTimeoutException ← TimeoutException,总用时 755 ms。", t=tl(S(4)), mark=lidx(S(4), 'R2dbcTimeoutException'), done=lidx(S(4), '默认的 R2DBC 连接池', 'max-size=3', 'max-size=30'), b=bars([['默认池:同时连接数', 10, '10(1100 ms)'], ['max-size=3:同时连接数', 3, '3(3182 ms)'], ['max-size=30:同时连接数', 30, '30(523 ms)'], ['max-acquire-time=200ms 失败的请求数', 8, '8']], 30, done=[0, 1, 2], mark=[3]), kv=KV([['默认连接池', '服务端最多同时 10 个连接'], ['池满', '请求排队,延迟线性增长'], ['max-acquire-time', '到期抛 R2dbcTimeoutException'], ['注意', '池大小要和数据库 max_connections、实例数一起算']], ['默认连接池'])),
]
A = mkartx('x61', 61, 'Spring,R2DBC,PostgreSQL,响应式,事务,连接池,真实验证,动画演示',
    '在本机 PostgreSQL 16 上实测 Spring Data R2DBC:repo.save 不订阅就不发 INSERT;没有事务时同一方法里的两条语句可能落在不同连接上(pid 不同),@Transactional 里则是同一个连接;失败回滚只在事务里生效,链外的 subscribe() 或 boundedElastic 上的 block() 写入的行不会回滚;默认连接池服务端最多同时 10 个连接,池满排队,max-acquire-time 到期抛 R2dbcTimeoutException。',
    'R2DBC 里 save() 为什么没写进去?没有事务时两条语句是同一个连接吗?事务里写 subscribe() 会怎样?连接池默认多大、满了会怎样?这篇在 Spring Boot 4.0.8 和本机 PostgreSQL 16 上逐个验证。',
    [('0 / 2', '保存两行再抛错:@Transactional 留下 0 行,没有事务留下 2 行'), ('1 行', '@Transactional 里 subscribe() 一个不接链的 save 再抛错,库里仍留下的行数'), ('10', '默认 R2DBC 连接池在服务端同时存在的连接数上限')],
    [('惰性', '<p>调用 repository 方法不发 SQL,订阅才发。</p>'),
     ('连接', '<p>事务外每条语句临时取连接,可能不是同一个;事务内绑定一个连接。</p>'),
     ('回滚', '<p>@Transactional 与 TransactionalOperator 能回滚;链外的 subscribe() / block() 不在事务里。</p>'),
     ('连接池', '<p>默认 10 个连接,满了排队,可设 max-acquire-time。</p>')],
    steps,
    [ENV_X + '。用 Spring Boot 4.0.8 的 SpringApplication(spring-boot-starter-data-r2dbc + r2dbc-postgresql 1.1.2,非 Web 模式);数据库是本机自己 initdb 出来的 PostgreSQL 16,端口 9601;服务端连接数每 50 ms 轮询 pg_stat_activity 取最大值,所以是近似值;pid 那一节是否同一个连接在不同次调用里不一定相同',
     '没有验证:MySQL / MariaDB / H2 的 R2DBC 驱动;R2dbcEntityTemplate 与派生查询方法;事务隔离级别与传播行为(@Transactional(propagation=...));连接池的空闲回收(max-idle-time)与预热;r2dbc-pool 的指标;批处理 Batch;读写分离;事务里调用外部 HTTP 服务的超时处理'],
    '事务与连接')
